with valid as (select *, substring(country, 1, 2) as country_prefix, upper(device) as device_upper from sessions where started_at >= to_timestamp('2023-11-18 04:00:00')), eligible as (select s.* from valid s where not exists (select 1 from web_events ch where ch.session_id = s.id and ch.event_time <= s.started_at)), with_window as (select s.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from eligible s inner join subscriptions sub on s.customer_id = sub.customer_id and s.started_at >= sub.start_date and s.started_at <= date_add(sub.end_date, 7)), latest as (select * from (select *, row_number() over (partition by device order by subscription_id, id, subscription_id) as rank_in_group from with_window) ranked where rank_in_group = 1), base as (select id, customer_id, browser, started_at, country_prefix, device_upper, subscription_id, plan, monthly_fee, initcap(trim(browser)) as browser_title, coalesce(browser, 'N/A') as browser_clean from latest where started_at > to_date('2023-12-25') and browser in ('Chrome', 'Firefox', 'Edge')) select id, customer_id, started_at, country_prefix, device_upper, subscription_id, browser_clean from base order by id nulls last;
